export function emptyQr() {
  return {
    kind: "url",
    value: "",
    pattern: "rounded",
    cornerSquare: "extra-rounded",
    cornerDot: "square",
    colour: "#0d1726",
    background: "#ffffff",
    level: "H",
    format: "png",
    logo: null,
  }
}

/**
 * The string the scanner actually receives.
 *
 * Empty in, empty out — the caller decides what to do about that, because a
 * placeholder encoded into a real downloadable file is a QR code somebody
 * prints and only discovers is wrong later.
 */
export function encodeValue(state) {
  const raw = String(state.value || "").trim()
  if (!raw) return ""

  if (state.kind === "phone") {
    return telHref(raw) || ""
  }

  if (state.kind === "email") {
    return `mailto:${raw}`
  }

  if (state.kind === "text") {
    return raw
  }

  // A website. Anything already carrying a scheme is left alone — including
  // the ones that are not http, because somebody pasting one meant it.
  if (/^[a-z][a-z0-9+.-]*:/i.test(raw)) return raw
  return `https://${raw.replace(/^\/+/, "")}`
}

/** True when the code would scan to nothing useful. */
export function qrProblem(state) {
  const raw = String(state.value || "").trim()
  if (!raw) return "Type where this code should take people."

  if (state.kind === "email" && !/.+@.+\..+/.test(raw)) {
    return "That does not look like an email address."
  }
  if (state.kind === "phone") {
    // telHref is deliberately generous — it keeps whatever dialable characters
    // it finds so an unusual number still works as a link. That is the wrong
    // rule HERE: "ridgeline.com4252392211" has digits in it and would quietly
    // become tel:4252392211, printed on a van, dialling a number nobody
    // checked. So this asks for a number it actually recognises.
    const international = raw.startsWith("+") && raw.replace(/\D/g, "").length >= 8
    if (!usDigits(raw) && !international) {
      return "That does not look like a phone number."
    }
  }
  return null
}

/** A filename somebody can find again in their downloads folder. */
export function qrFilename(state) {
  const base = String(state.value || "qr-code")
    .trim()
    .toLowerCase()
    .replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40)
  return base ? `qr-${base}` : "qr-code"
}

/**
 * The options object `qr-code-styling` is constructed and updated with.
 *
 * The margin is the QUIET ZONE, and it is not decoration: scanners need clear
 * space around a code to find its edges, and one exported hard against its own
 * border is the single most common reason a printed code will not read. It is
 * baked into the download on purpose, because whoever places the file on a
 * sign cannot be relied on to leave room for it.
 */
export function qrOptions(state, { size = 320 } = {}) {
  return {
    width: size,
    height: size,
    type: "svg",
    data: encodeValue(state) || " ",
    margin: 8,
    image: state.logo || undefined,
    qrOptions: { errorCorrectionLevel: state.level },
    imageOptions: {
      crossOrigin: "anonymous",
      margin: 4,
      imageSize: 0.36,
      hideBackgroundDots: true,
    },
    dotsOptions: { color: state.colour, type: state.pattern },
    backgroundOptions: { color: state.background },
    cornersSquareOptions: { color: state.colour, type: state.cornerSquare },
    cornersDotOptions: { color: state.colour, type: state.cornerDot },
  }
}
